import java.net.URL;
import java.util.HashMap;
import java.util.Map;

@RunWith(MockitoJUnitRunner.class)
public class UrlBuilderTest {

    @Mock
    private Connection.KeyVal kv;

    @Test
    public void buildEmptyUrl() {
        UrlBuilder builder = new UrlBuilder(null);
        URL url = builder.build();
        Mockito.verifyNoInteractions(url);
    }

    @Test
    public void buildUrlWithKeyAndValue() {
        Map<String, String> map = new HashMap<>();
        map.put("key", "value");
        UrlBuilder builder = new UrlBuilder(new URL("https://example.com"));
        Connection.KeyVal keyVal = new Connection.KeyVal(map);
        builder.appendKeyVal(keyVal);
        URL url = builder.build();
        Mockito.verifyNoInteractions(url);
    }

    @Test
    public void buildUrlWithQuery() {
        Map<String, String> map = new HashMap<>();
        map.put("key1", "value1");
        map.put("key2", "value2");
        UrlBuilder builder = new UrlBuilder(new URL("https://example.com"));
        Connection.KeyVal keyVal = new Connection.KeyVal(map);
        builder.appendKeyVal(keyVal);
        String query = "key1=value1&key2=value2";
        Mockito.when(kv.getKeyValues()).thenReturn(query);
        URL url = builder.build();
        org.junit.Assert.assertTrue(url.toString().contains("?"));
    }

    @Test
    public void buildUrlWithFragment() {
        Map<String, String> map = new HashMap<>();
        map.put("key1", "value1");
        map.put("key2", "value2");
        UrlBuilder builder = new UrlBuilder(new URL("https://example.com#fragment"));
        Connection.KeyVal keyVal = new Connection.KeyVal(map);
        builder.appendKeyVal(keyVal);
        String fragment = "fragment";
        Mockito.when(kv.getKeyValues()).thenReturn("#" + fragment);
        URL url = builder.build();
        org.junit.Assert.assertTrue(url.toString().endsWith(fragment));
    }

    @Test
    public void appendKeyValue() {
        UrlBuilder builder = new UrlBuilder(new URL("https://example.com"));
        Connection.KeyVal keyVal = new Connection.KeyVal();
        builder.appendKeyVal(keyVal);
        Mockito.verify(builder).appendQueryValues(Mockito.anyString());
    }

    @Test
    public void appendKeyValueWithEncodedValue() {
        UrlBuilder builder = new UrlBuilder(new URL("https://example.com"));
        Map<String, String> map = new HashMap<>();
        map.put("key", "value");
        Connection.KeyVal keyVal = new Connection.KeyVal(map);
        Mockito.when(keyVal.getKeyValues()).thenReturn("key=value");
        builder.appendKeyVal(keyVal);
        Mockito.verify(builder).appendQueryValues("key=%3Dvalue");
    }

    @Test
    public void appendKeyValueWithMultipleEntries() {
        UrlBuilder builder = new UrlBuilder(new URL("https://example.com"));
        Map<String, String> map = new HashMap<>();
        map.put("key1", "value1");
        map.put("key2", "value2");
